package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="spms_intervention_checkpoint",uniqueConstraints=@UniqueConstraint(name="uk_spms_checkpoint_due",columnNames={"agency_id","intervention_id","due_on"}))public class PerformanceInterventionCheckpoint extends RspAuditedEntity{public enum Status{PLANNED,COMPLETED,VERIFIED}@Column(name="intervention_id",nullable=false,length=36)private String interventionId;@Column(name="due_on",nullable=false)private LocalDate dueOn;@Column(nullable=false,length=2000)private String objective;@Column(name="progress_note",length=4000)private String progressNote;@Column(name="employee_visible_feedback",length=4000)private String employeeVisibleFeedback;@Column(name="private_pmt_note",length=4000)private String privatePmtNote;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="completed_by",length=100)private String completedBy;@Column(name="completed_at")private Instant completedAt;protected PerformanceInterventionCheckpoint(){}public PerformanceInterventionCheckpoint(String a,String intervention,LocalDate due,String objective){super(a);interventionId=requiredText(intervention,"interventionId");dueOn=due;if(due==null)throw new IllegalArgumentException("dueOn is required");this.objective=requiredText(objective,"objective");status=Status.PLANNED;}public void complete(String progress,String feedback,String privateNote,String actor,Instant at){if(status!=Status.PLANNED)throw new IllegalStateException("Only a planned checkpoint may be completed");progressNote=requiredText(progress,"progressNote");employeeVisibleFeedback=optionalText(feedback);privatePmtNote=optionalText(privateNote);completedBy=requiredText(actor,"actor");completedAt=at;status=Status.COMPLETED;}public void verify(){if(status!=Status.COMPLETED)throw new IllegalStateException("Only a completed checkpoint may be verified");status=Status.VERIFIED;}public String getInterventionId(){return interventionId;}public LocalDate getDueOn(){return dueOn;}public String getObjective(){return objective;}public String getProgressNote(){return progressNote;}public String getEmployeeVisibleFeedback(){return employeeVisibleFeedback;}public String getPrivatePmtNote(){return privatePmtNote;}public Status getStatus(){return status;}public String getCompletedBy(){return completedBy;}public Instant getCompletedAt(){return completedAt;}}
